 if(req.method==="POST"&&req.url==="/v1/current-prices")return body(req,async(err,b)=>{if(err||!pool||!b||!clean(b.product)||!Array.isArray(b.merchants))return send(res,400,{error:"Ungültige Anfrage"});const days=Math.max(1,Math.min(30,Number(b.maxAgeDays||7))),today=clean(b.today)||new Date().toISOString().slice(0,10);const q=await pool.query('SELECT po.id,po.product_id AS "productId",po.gtin,po.product,po.store,po.store_id AS "storeId",po.region,po.price::float,po.per,po.date::text,po.observed_at AS "observedAt",po.valid_from AS "validFrom",po.valid_to AS "validTo",po.price_type AS "priceType",po.source,po.proof,po.currency,psh.health_score AS "sourceHealthScore",psh.state AS "sourceHealthState" FROM price_observations po LEFT JOIN LATERAL (SELECT health_score,state FROM price_source_health h WHERE h.source=po.source ORDER BY calculated_at DESC LIMIT 1) psh ON true WHERE po.date >= ($1::date - ($2::int * interval \'1 day\')) OR po.valid_to >= $1::date',[today,days]);const results=CurrentPrice.compare({name:clean(b.product),gtin:clean(b.gtin)||null,brand:clean(b.brand)||null,pack:clean(b.pack)||null},b.merchants.map(clean),q.rows,{today,maxAgeDays:days,storeId:clean(b.storeId)||null,region:clean(b.region)||null,eligibility:b.eligibility&&typeof b.eligibility==="object"?b.eligibility:{},quantity:Number(b.quantity||1)});const coverage=PriceCoverage.summarize(results),qualityGate=PriceCoverage.ready(coverage),leaders=CurrentPrice.leaders(results);return send(res,200,{ok:true,product:clean(b.product),today,results,leaders,coverage,qualityGate})});
